import { useTranslation } from 'react-i18next';

export function Banner({ count }) {
  const { t } = useTranslation();
  return (
    <div className="banner" title="Shown to everyone">
      <h2>{t('banner.title')}</h2>
      <p>Welcome back</p>
      <span>{count} items</span>
    </div>
  );
}
